# ==============================================================================# 081_INTEGRATION_EXECUTION_ENGINE.py## IOTEC Integration Execution Engine# ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class IntegrationExecutionEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS integration_execution(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            execution_id TEXT,            plan_id TEXT,            capability TEXT,            current_step TEXT,            progress REAL,            execution_status TEXT,            evidence TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self, payload):        raw = json.dumps(            payload,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_step(        self,        plan_id,        capability,        current_step,        progress,        execution_status,        evidence,        metadata=None    ):        metadata = metadata or {}        timestamp = datetime.utcnow().isoformat()        execution_id = hashlib.md5(            f"{timestamp}{plan_id}{current_step}".encode()        ).hexdigest()        payload = {            "timestamp": timestamp,            "execution_id": execution_id,            "plan_id": plan_id,            "capability": capability,            "current_step": current_step,            "progress": progress,            "execution_status": execution_status,            "evidence": evidence,            "metadata": metadata        }        signature = self._hash(payload)        self.conn.execute("""        INSERT INTO integration_execution(            timestamp,            execution_id,            plan_id,            capability,            current_step,            progress,            execution_status,            evidence,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["execution_id"],            payload["plan_id"],            payload["capability"],            payload["current_step"],            payload["progress"],            payload["execution_status"],            payload["evidence"],            json.dumps(payload["metadata"], ensure_ascii=False),            signature        ))        self.conn.commit()        payload["hash"] = signature        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = IntegrationExecutionEngine()    evento = engine.register_step(        plan_id="bd95e0a4912d45a7634406de49b3dafa",        capability="BASE_EMPRESARIAL",        current_step="Selecionar fornecedor",        progress=20,        execution_status="EM_EXECUÇÃO",        evidence="Plano aprovado pela Governança e primeira etapa iniciada.",        metadata={            "origin":"080_INTEGRATION_PLANNING_ENGINE",            "responsible":"INTEGRATION_EXECUTION_ENGINE"        }    )    print("="*80)    print("INTEGRATION EXECUTION")    print("="*80)    for k,v in evento.items():        print(f"{k:22}: {v}")    print("="*80)